import fs from 'node:fs';

const file = process.argv[2];
const lines = fs.readFileSync(file, 'utf8').split('\n').filter(Boolean);

function truncate(s, n) {
  if (typeof s !== 'string') s = JSON.stringify(s);
  s = s.replace(/\s+/g, ' ').trim();
  return s.length > n ? s.slice(0, n) + '…' : s;
}

for (const line of lines) {
  let obj;
  try { obj = JSON.parse(line); } catch { continue; }
  const ts = obj.timestamp || '';
  if (obj.type === 'queue-operation') continue;
  if (obj.type === 'attachment') continue;
  const msg = obj.message;
  if (!msg) continue;
  const role = msg.role;
  const content = msg.content;
  if (typeof content === 'string') {
    if (content.trim()) console.log(`[${ts}] ${role} TEXT: ${truncate(content, 400)}`);
    continue;
  }
  if (!Array.isArray(content)) continue;
  for (const block of content) {
    if (block.type === 'text') {
      if (block.text && block.text.trim()) console.log(`[${ts}] ${role} TEXT: ${truncate(block.text, 400)}`);
    } else if (block.type === 'tool_use') {
      console.log(`[${ts}] ${role} TOOL_USE ${block.name}: ${truncate(block.input, 300)}`);
    } else if (block.type === 'tool_result') {
      const c = block.content;
      let text = '';
      if (typeof c === 'string') text = c;
      else if (Array.isArray(c)) text = c.map(x => x.text || '').join(' ');
      console.log(`[${ts}] ${role} TOOL_RESULT${block.is_error ? ' ERROR' : ''}: ${truncate(text, 250)}`);
    }
  }
}

